internal fun RuntimeEngine.wrap(type: String, value: JsonElement, parent: RuntimeHandle?): RuntimeHandle? {
    if (value is JsonNull) return null
    val id = value.jsonPrimitive.content
    return when(type) {
        "Dataset" -> BundledDataset(this, id, parent)
        "Driver" -> BundledDriver(this, id, parent)
        "Band" -> BundledBand(this, id, parent)
        "SpatialReference" -> BundledSpatialReference(this, id, parent)
        "CoordinateTransformation" -> BundledCoordinateTransformation(this, id, parent)
        "GCP" -> BundledGCP(this, id, parent)
        "Layer" -> BundledLayer(this, id, parent)
        "Feature" -> BundledFeature(this, id, parent)
        "FeatureDefn" -> BundledFeatureDefn(this, id, parent)
        "FieldDefn" -> BundledFieldDefn(this, id, parent)
        "GeomFieldDefn" -> BundledGeomFieldDefn(this, id, parent)
        "Geometry" -> BundledGeometry(this, id, parent)
        else -> error("Unknown GDAL handle type: $type")
    }
}
internal fun RuntimeEngine.wrapDataset(value: JsonElement, parent: RuntimeHandle?): Dataset? = wrap("Dataset", value, parent) as Dataset?
